contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint minSum, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "not enough balance");

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint beforeBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(
            reverted ||
            afterBalance == beforeBalance ||
            afterBalance + collectAmount == beforeBalance
        );
    }

    receive() external payable {}
}

